import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

import '../../integration_test/helpers/live_test_tls.dart';

void main() {
  group('live test TLS trust', () {
    test(
      'disabled extra root uses platform trust even with an invalid value',
      () {
        final trust = LiveTestTlsTrust.fromEncodedRoot(
          enabled: false,
          encodedRoot: 'not-base64',
        );

        expect(trust.usesExtraRoot, isFalse);
        expect(trust.createSecurityContext(), isA<SecurityContext>());
      },
    );

    test('enabled valid certificate creates an additive trust context', () {
      final trust = _testTrust();

      expect(trust.usesExtraRoot, isTrue);
      expect(trust.createSecurityContext(), isA<SecurityContext>());
      expect(
        LiveTestTlsTrust.fromEncodedRoot(
          enabled: true,
          encodedRoot: _testServerCertificatePemBase64,
        ).usesExtraRoot,
        isTrue,
      );
    });

    test(
      'enabled missing, malformed, private, and oversized roots fail closed',
      () {
        final invalidRoots = <String>[
          '',
          'not-base64',
          base64Encode(utf8.encode('not a certificate')),
          _testServerPrivateKeyPemBase64,
          base64Encode(Uint8List(maximumLiveTestRootPemBytes + 1)),
          base64Encode(
            utf8.encode(
              '-----BEGIN CERTIFICATE-----\nZm9v\n'
              '-----END CERTIFICATE-----\n',
            ),
          ),
        ];

        for (final encodedRoot in invalidRoots) {
          expect(
            () => LiveTestTlsTrust.fromEncodedRoot(
              enabled: true,
              encodedRoot: encodedRoot,
            ),
            throwsA(isA<LiveTestTlsConfigurationException>()),
          );
        }
      },
    );

    test(
      'native TLS enforces both trusted chain and requested hostname',
      () async {
        expect(HttpOverrides.current, isNull);
        final serverContext = SecurityContext()
          ..useCertificateChainBytes(
            base64Decode(_networkTestServerChainPemBase64),
          )
          ..usePrivateKeyBytes(
            base64Decode(_networkTestServerPrivateKeyPemBase64),
          );
        final server = await HttpServer.bindSecure(
          InternetAddress.loopbackIPv4,
          0,
          serverContext,
        );
        final subscription = server.listen((request) async {
          request.response.write('trusted');
          await request.response.close();
        });
        addTearDown(() async {
          await subscription.cancel();
          await server.close(force: true);
        });
        final uri = Uri.parse('https://localhost:${server.port}/health');

        final untrustedClient = HttpClient(
          context: SecurityContext(withTrustedRoots: false),
        );
        addTearDown(() => untrustedClient.close(force: true));
        await expectLater(
          _status(untrustedClient, uri),
          throwsA(isA<HandshakeException>()),
        );

        final networkTrust = LiveTestTlsTrust.fromEncodedRoot(
          enabled: true,
          encodedRoot: _networkTestCaCertificatePemBase64,
        );
        final trustedClient = HttpClient(
          context: networkTrust.createSecurityContext(
            baseContext: SecurityContext(withTrustedRoots: false),
          ),
        );
        addTearDown(() => trustedClient.close(force: true));
        expect(await _status(trustedClient, uri), HttpStatus.ok);

        final wrongHostnameClient = createLiveTestHttpClient(
          trust: networkTrust,
        );
        wrongHostnameClient.findProxy = (_) => 'DIRECT';
        wrongHostnameClient.connectionFactory =
            (uri, proxyHost, proxyPort) async {
              return ConnectionTask.fromSocket(
                Socket.connect(InternetAddress.loopbackIPv4, server.port),
                () {},
              );
            };
        addTearDown(() => wrongHostnameClient.close(force: true));
        await expectLater(
          _status(
            wrongHostnameClient,
            Uri.parse('https://wrong.weave.test:${server.port}/health'),
          ),
          throwsA(anyOf(isA<HandshakeException>(), isA<HttpException>())),
        );
      },
    );

    test('live HTTP helpers contain no certificate-verification bypass', () {
      final helperFiles = <String>[
        'integration_test/helpers/live_oidc_test_driver.dart',
        'integration_test/helpers/live_test_tls.dart',
        'integration_test/helpers/test_http_overrides.dart',
      ];

      for (final path in helperFiles) {
        expect(
          File(path).readAsStringSync(),
          isNot(contains('badCertificateCallback')),
          reason: '$path must rely on native chain and hostname validation.',
        );
      }
    });
  });
}

LiveTestTlsTrust _testTrust() {
  return LiveTestTlsTrust.fromEncodedRoot(
    enabled: true,
    encodedRoot: _testCaCertificatePemBase64,
  );
}

Future<int> _status(HttpClient client, Uri uri) async {
  final request = await client.getUrl(uri);
  final response = await request.close();
  await response.drain<void>();
  return response.statusCode;
}

// Test-only CA, leaf certificate, and key for the loopback TLS server. The
// leaf carries SANs for 127.0.0.1 and localhost. None is production material.
const _testCaCertificatePemBase64 =
    '';

const _testServerCertificatePemBase64 =
    '';

const _testServerPrivateKeyPemBase64 =
    '';

// The native-network fixture uses a complete root/intermediate/leaf chain.
// Its leaf expires 2028-10-09 and must be rotated before that date.
const _networkTestCaCertificatePemBase64 =
    '';

const _networkTestServerChainPemBase64 =
    '';

const _networkTestServerPrivateKeyPemBase64 =
    '';
